rows=[]
def add(category,title,question,model,ensemble,observable,oracle,sources,acceptance,resources='T1',adapter='PLANNED_ADAPTER',mapping='',overlap='Different physical observable, ensemble or error question; not a repeated parameter arm.',constraints='Match Hamiltonian, boundary, particle sector/ensemble, energy zero and natural-log entropy convention.'):
 prefix={'Analytical':'A','Independent package':'P','External-reference error control':'X'}[category]
 i=1+sum(r['category']==category for r in rows)
 rows.append(dict(id=f'{prefix}{i:02d}',category=category,title=title,scientific_question=question,model_geometry=model,ensemble=ensemble,observable_normalization=observable,external_oracle=oracle,source_urls=' | '.join(URL.get(s,s) for s in sources),matching_constraints=constraints,acceptance=acceptance,resource_tier=resources,resource_notes='Unmeasured planning tier; a timing/precision pilot is required before an allocation estimate.',adapter_status=adapter,execution_status='NOT_RUN_AS_DEFINED',initial_batch_mapping=mapping or 'No direct coverage in initial 100 comparisons.',overlap_note=overlap))
